import{z as i,x as s,o as t,c as p,q as l,j as n,D as e,d as A,s as o,S as B,b as a}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"总量管制与许可证","description":"","frontmatter":{"title":"总量管制与许可证","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/cap-and-trade.md","filePath":"econ/cap-and-trade.md","lastUpdated":1791063341000}'),m={name:"econ/cap-and-trade.md"};function d(D,E,C,M,h,u){const r=s("Mermaid");return t(),p("div",null,[E[2]||(E[2]=l('<h1 id="总量管制与许可证" tabindex="-1">总量管制与许可证 <a class="header-anchor" href="#总量管制与许可证" aria-label="Permalink to &quot;总量管制与许可证&quot;">​</a></h1><div class="epigraph"><p>先把允许的排放钉成总量，再把许可证交给市场去交易；竞争许可市场把减污做到等边际，初始分配只改谁付钱。</p><footer>—— 据 Dales, Pollution, Property and Prices, 1968；Montgomery, Markets in Licenses and Efficient Pollution Control Programs, Journal of Economic Theory, 1972 整理</footer></div><p><a href="/econ/coase-theorem">上一课</a>（科斯定理与交易成本）。零成本谈判下，排放权的初始归属只改分配，不改有效 \\(q^*\\)。本课不重写相互性与摩擦那一半。缺口是政策工具：计划者若不能一对一谈判，也不想猜准<a href="/econ/externality-pigou">庇古</a>税率，能否发一笔可交易许可，让市场去找同一点？Dales 提出把环境当成可分割产权；Montgomery 证明竞争许可市场达到成本有效。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>庇古税钉价格 \\(t=\\mathrm{MD}(q^*)\\)，数量内生。科斯说权利可交易。总量管制选 \\(Q^*\\)（希望 \\(Q^*=Q_{\\mathrm{社会最优}}\\)），发许可 \\(\\sum e_i\\le Q^*\\)，允许转卖。竞争下许可价格 \\(p_{\\ell}\\) 使各厂减污的边际成本对齐到 \\(p_{\\ell}\\)，总减污成本最小——不管许可最初发给谁（科斯在政策上的版本）。缺口不是再画 \\(\\mathrm{MD}\\)，而是：<strong>数量工具与价格工具何时等价，初始分配改什么、不改什么。</strong></p><p>厂商成本异质时，命令式「每家减同样百分比」不是成本有效。许可交易正是为了让减污发生在 MAC 低的厂。税也能对齐 MAC（大家都面对同一 \\(t\\)）；差别在不确定与政治：税把价格钉死、排放浮动；封顶把数量钉死、许可价浮动。</p><p><span class="marginnote">MAC（边际减排成本）就是「多减一吨要额外花多少钱」：换燃料便宜的厂 MAC 低，要重建生产线的厂 MAC 高。许可市场的全部作用，就是让减污自动落在 MAC 最低的那些厂——便宜的厂多减排、卖许可赚钱，贵的厂买许可省下改造费，总账最省。</span></p><h3 id="可交易许可不是庇古税换了单位" tabindex="-1">可交易许可不是庇古税换了单位 <a class="header-anchor" href="#可交易许可不是庇古税换了单位" aria-label="Permalink to &quot;可交易许可不是庇古税换了单位&quot;">​</a></h3><p>确定性、完全信息、竞争下，选 \\(Q^*\\) 使 \\(p_{\\ell}=\\mathrm{MD}(Q^*)\\)，与选 \\(t=\\mathrm{MD}\\) 同一配置。等价在 Weitzman 的斜率比较下破裂：MAC 不确定时，数量与价格的相对优劣取决于 \\(\\mathrm{MD}\\) 与 MAC 谁更陡。本课先钉确定基准，不确定放边界。</p><p><span class="marginnote">Montgomery 1972：许可在空间上若要对应扩散，许可证应分地点或用转换系数，否则交易会把污染赶到敏感区。教具先当均匀混合污染物，一单位许可一单位排放。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：竞争厂商、许可可分可转卖、无市场势力。成本有效：\\(\\min\\sum C_i(e_i)\\) s.t. \\(\\sum e_i\\le Q^*\\)。许可市场的 \\(p_{\\ell}\\) 是该约束的乘数。初始分配 \\(e_i^0\\) 只改谁向谁买许可，不改 \\(e_i^*\\)（科斯）。计划者仍要选对 \\(Q^*\\)；选错总量，交易只能在错误的帽子里做成本有效，不能把帽子本身纠正到社会最优。</p><p>与命令控制对照：同样 \\(Q^*\\)，不许交易则 MAC 不对齐，同样环境目标更贵。税：计划者要猜 \\(t\\)；许可：猜 \\(Q\\)。信息负担从税率挪到总量，不是消失。拍卖发放把租金收进预算；免费发放只改分配，竞争下不改 \\(e_i^*\\)。</p>',13)),(t(),n(B,null,{default:e(()=>[o(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20COASE%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E6%9D%83%E5%88%A9%E5%8F%AF%E8%B0%88%22%5D%20--%3E%20CAP%5B%22%E6%94%BF%E7%AD%96%EF%BC%9A%E9%92%89%20Q*%20%E5%86%8D%E8%AE%A9%E8%AE%B8%E5%8F%AF%E4%BA%A4%E6%98%93%22%5D%0A%20%20PIGOU%5B%22%E5%BA%87%E5%8F%A4%EF%BC%9A%E9%92%89%20t%22%5D%20--%3E%20EQV%5B%22%E7%A1%AE%E5%AE%9A%E4%B8%8B%E5%8F%AF%E7%AD%89%E4%BB%B7%22%5D%0A%20%20CAP%20--%3E%20MAC%5B%22%E7%AB%9E%E4%BA%89%E8%AE%B8%E5%8F%AF%EF%BC%9AMAC%20%E5%AF%B9%E9%BD%90%22%5D%0A%20%20CAP%20--%3E%20DIST%5B%22%E5%88%9D%E5%A7%8B%E5%88%86%E9%85%8D%E5%8F%AA%E6%94%B9%E8%B0%81%E4%BB%98%E9%92%B1%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"人数很多时，科斯谈判组不起来，许可市场用价格代替双边讨价还价——这是把权利标准化之后的匿名交易，不是全人口联盟。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"对齐 MAC 的机制与要素市场同一：共同 \\(p_{\\ell}\\) 让每家的减污一阶条件相同。初始分配无关效率的机制就是科斯：许可是禀赋，交易补全这维商品。税与数量在确定下等价的机制是：一条向下的 \\(\\mathrm{MD}\\) 与一条向上的 MAC，交点既可用纵轴的税、也可用横轴的帽去钉。",-1)),E[6]||(E[6]=a("p",null,"计划者仍须知道有效点才能选对帽——与庇古要知道 \\(\\mathrm{MD}(q^*)\\) 是对称的信息。许可的政治优点往往是：把 \\(Q^*\\) 当成环境目标更可沟通，再让市场找谁减。",-1)),E[7]||(E[7]=a("p",null,"Weitzman：MAC 随机时，税锁定边际激励、排放浮动；帽锁定排放、许可价浮动。\\(\\mathrm{MD}\\) 很陡（阈值损害）时数量工具更安全；MAC 很陡时价格工具少付「选错帽」的成本。本课确定基准上二者等价，不确定时要另写损失函数，不要口头说「许可永远优于税」。",-1)),E[8]||(E[8]=a("p",null,[a("span",{class:"marginnote"},"许可市场若被少数厂操纵，\\(p_{\\ell}\\) 不再等于影子成本，成本有效失败。这与产品市场势力是同一缺口，不是科斯零成本假设的一部分。")],-1)),(t(),n(B,null,{default:e(()=>[o(r,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E5%87%8F%E6%8E%92%E6%88%90%E6%9C%AC%20MAC%20%E4%B8%8D%E7%A1%AE%E5%AE%9A%22%5D%20--%3E%20P1%5B%22%E4%BB%B7%E6%A0%BC%E5%B7%A5%E5%85%B7%3A%20%E9%92%89%E6%AD%BB%E7%A8%8E%20t%22%5D%0A%20%20P1%20--%3E%20O1%5B%22%E6%8E%92%E6%94%BE%E9%87%8F%E6%B5%AE%E5%8A%A8%22%5D%0A%20%20U%20--%3E%20P2%5B%22%E6%95%B0%E9%87%8F%E5%B7%A5%E5%85%B7%3A%20%E9%92%89%E6%AD%BB%E5%B8%BD%20Q%22%5D%0A%20%20P2%20--%3E%20O2%5B%22%E8%AE%B8%E5%8F%AF%E4%BB%B7%E6%B5%AE%E5%8A%A8%22%5D%0A%20%20D1%5B%22%E6%8D%9F%E5%AE%B3%20MD%20%E5%BE%88%E9%99%A1%3A%20%E9%98%88%E5%80%BC%E5%9E%8B%E6%8D%9F%E5%AE%B3%22%5D%20--%3E%20W1%5B%22%E9%80%89%E6%95%B0%E9%87%8F%E5%B8%BD%3A%20%E6%8E%92%E6%94%BE%E8%B6%85%E9%99%90%E7%9A%84%E4%BB%A3%E4%BB%B7%E4%B8%8D%E5%8F%AF%E6%89%BF%E5%8F%97%22%5D%0A%20%20D2%5B%22MAC%20%E5%BE%88%E9%99%A1%3A%20%E5%87%8F%E6%8E%92%E6%88%90%E6%9C%AC%E6%95%8F%E6%84%9F%22%5D%20--%3E%20W2%5B%22%E9%80%89%E7%A8%8E%3A%20%E9%81%BF%E5%85%8D%E9%94%81%E6%AD%BB%E9%94%99%E8%AF%AF%E6%80%BB%E9%87%8F%22%5D%0A%20%20W1%20--%3E%20R%5B%22Weitzman%20%E8%A7%84%E5%88%99%3A%20%E6%AF%94%20MD%20%E4%B8%8E%20MAC%20%E8%B0%81%E6%9B%B4%E9%99%A1%22%5D%0A%20%20W2%20--%3E%20R%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[9]||(E[9]=l('<p><span class="marginnote">直觉类比：总量帽子像一张只印 Q 张的停车证。证先发给我还是你，改变的是谁最后掏钱买证；只要证能转卖，最终总是最离不开车的人持证——停车总量不变，付款人变了。这就是「初始分配只改分配、不改效率」的停车证版本。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>银行把单期帽拉成跨期路径，仍靠竞争许可对齐跨期 MAC。</p><p>热点、跨界输送，要分区许可或交换比率，Montgomery 的空间版本。动态银行（banking）把帽跨期，本课单期。免费发放与拍卖只改分配与公共收入，不改竞争下的 \\(e_i^*\\)——除非市场势力或流动性约束让有人买不起许可。下一课<a href="/econ/public-goods">公共物品</a>把非排他推到极端：许可假定排放可测、可排除未持证者；纯公共品连「不付费者不享用」都做不到。</p><p>后课默认：可交易许可在竞争下成本有效，初始分配只改分配；与庇古税在确定世界等价，帽选错则有效点一起错。</p><p>本课不把许可市场写成一对一科斯谈判。</p><p><span class="marginnote">常见误区：把「许可优于税」当口号背。确定世界里两者可以完全等价；不确定下谁更稳，取决于损害曲线与减排成本曲线谁更陡——阈值型损害（MD 陡）该用数量帽，成本敏感（MAC 陡）该用税。没有损失函数就说「永远优于」，是这一课明令禁止的口头结论。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>总量钉住环境目标，交易把减污分给 MAC 低的厂。</li><li>竞争许可是标准化的科斯权利，不是一对一谈判。</li><li>确定下与庇古税等价；不确定下价格对数量要另比斜率。</li><li>下一课：不能排除的公共品，连许可都组不起来。</li><li>出处：Dales, 1968；Montgomery, <em>JET</em>, 1972。</li></ul>',9))])}const c=i(m,[["render",d]]);export{_ as __pageData,c as default};
